data.query:
query (
  $workcenterId: String!,
  $outputId: Int!
){
  productionSetupOutput(
    where:{
      workcenterId:{ _eq: $workcenterId}
      outputId:{ _eq: $outputId}
    }
  ){
    edges{
      node{
        autoProduction
        standardQuantity
      }
    }
  }
}

query (
  $groupId: String!,
  $plcCode: String!
){
  modeGroup(
    where:{
      id:{ _eq: $groupId}      
    }
  ) {
    total
    edges {
      node {
        id
        name
        modeList(where:{
          plcCode:{ _eq: $plcCode}
        }) {
          total
          edges {
            node {
              id
              plcCode
              modeId
            }
          }
        }
      }
    }
  }
}

